\label{thm:main}
Let $d$ and $n$ be positive integers, and
$E/F$ be a separable field extension of degree $m  \colonequals \binom{n+d}{n}$. Assume that $|F|>2$. Then there exists a point $P\in\mathbb{P}^n(E)$ such that $P$ does not lie on any hypersurface of degree $d$ defined over $F$.

\label{lem.split-case}
Let $F$ be an infinite field, $d$ and $n$ be positive integers, and $\displaystyle m =  \binom{n+d}{n}$. Then there exist 
$P_1, \ldots, P_m \in \mathbb{P}^n(F)$ such that no degree $d$ hypersurface in $\mathbb{P}^n$ passes through $P_1, \ldots, P_m$.

\label{prop:sharper-bounds} 
Let $t$ denote the fraction of hypersurfaces in $\mathbb{P}^{n}$ of degree $d$ over $\mathbb{F}_q$ 
that are geometrically reducible.  Assume that one of the following conditions holds: 
\begin{itemize}
\item $n= 2$, $d\geqslant 6$ and  $q\geqslant 3$; or
\item $n\geqslant 3$, $d\geqslant 3$ and $q\geqslant 3$.
\end{itemize} 
Then $(d-1) tq \leqslant 2$.

\label{lem:1001}
Assume $2(i+1) \leqslant d$.
Then

\begin{itemize}
\item[(a)] $N_{i+1} - N_i \geqslant d-2i-1$; and
\item[(b)] $N_{i+1} - N_1 \geqslant d - 3$.
\end{itemize}

(a) Using Pascal's identity recursively, we rewrite $N_{i+1} - N_i$ as
\begin{align*}
N_{i + 1} - N_i & = \binom{n+d-i-1}{n-1} - \binom{n+i}{n-1} \\
& = \sum_{j=0}^{d-i} \binom{n-2+j}{n-2} - \sum_{j=0}^{i+1}\binom{n-2+j}{n-2} \\
& = \sum_{j=i+2}^{d-i} \binom{n-2+j}{n-2}
\end{align*}
The above sum has $(d-i) - (i-1) = d - 2i + 1 \geqslant 1$ terms by our assumption on $i$. Moreover, each term
$\geqslant 1$, so the sum is $\geqslant d - 2i + 1$, as desired.

\smallskip
(b) Write
$N_{i+1} - N_{1}  = (N_{i+1} - N_i) + (N_i - N_{i-1}) + \ldots + (N_2 - N_1)$.
Part~(a) tells us that each term in this sum is non-negative, and the last term, $N_2 - N_1$, is $\geqslant d - 3$.
Thus
\begin{equation}
\label{e.t1-2}
N_{i+1} - N_{1}  = (N_{i+1} - N_i) + (N_i - N_{i-1}) + \ldots + (N_2 - N_1) \geqslant N_2-N_1\geqslant d-3,
\end{equation}
as desired.

\label{lem:1003}
If $n\geqslant 2$ and $d,q\geqslant 3$, then  for each divisor $e>1$ of $d$, we have: 
\begin{equation}
\label{eq:ineq.M_e}
M_e \geqslant  \frac{1}{4}\binom{n}{2} d^2 - d + 1.
\end{equation}

It is shown in the proof of \cite{Poo04}*{Proposition 2.7} that 
\begin{equation} \label{e.t1}
t_1 \leqslant \sum_{i=1}^{\lfloor d/2\rfloor} q^{-N_i},
\end{equation}
where $\displaystyle N_i = \binom{n+d}{d} - \binom{n+i}{n} - \binom{n+d-i}{n}$, as in~\eqref{eq:N_i}.
Parts (a) and (b) now follow from Lemma~\ref{lem.u1}(a) and (b), respectively. (Note that the right hand side of the inequality~\eqref{e.t1} is denoted by $u_1$ in the statement of Lemma~\ref{lem.u1}.)

It is shown in the proof of \cite{Poo04}*{Proposition 2.7} that
\begin{equation} \label{e.t2}
t_2 \leqslant\sum_{e|d, e>1} q^{-M_e}
\end{equation}
where $\displaystyle M_e = \binom{d+n}{n}-e\binom{d/e+n}{n}$.  The desired conclusion now follows from Lemma~\ref{lem.u2}. (Note that the right hand side of the inequality~\eqref{e.t2} is denoted by $u_2$ in the statement of Lemma~\ref{lem.u2}.)

If $n\geqslant  2$, $q\geqslant 3$ and $d\geqslant 3$, then we have  \begin{align*}
    (d-1)(d-2) q^{m(n-3/2)} + (q^{m(n-2)} + \cdots + q^m+1) + 5d^{13/3} q^{m(n-2)} <  q^{m(n-1)-1}
\end{align*} 
In order to verify this inequality, we first note that
\begin{equation}
\label{eq:lower_2}
q^{m(n-2)}+\cdots + q^m+1=\frac{q^{m(n-1)}-1}{q^m-1}< \frac{q^{m(n-1)}}{q^m-1}< \frac{q^{m(n-1)}}{1000q},
\end{equation}
since $q\geqslant 3$ and $m\geqslant (d+2)(d+1)/2\geqslant 10$ because $d\geqslant 3$. Employing \eqref{eq:lower_2}, we see that
the left-hand side of the inequality in the Claim is less than
\begin{equation}
\label{eq:lower_3}
(d-1)(d-2)q^{m(n-3/2)}+\frac{q^{m(n-1)-1}}{1000}+ 5d^{13/3}q^{m(n-2)}.
\end{equation}  
Dividing the expression from \eqref{eq:lower_3} by $q^{m(n-1)-1}$, we can easily check 
$$(d-1)(d-2)q^{1-m/2}+\frac{1}{1000}+5d^{13/3}q^{1-m}<1,$$
keeping in mind that $q\geqslant 3$ and $m\geqslant (d+2)(d+1)/2$, while $d\geqslant 3$. This completes the proof of the Claim.

\label{rem.harmless}
Note that the assumption that $d \geqslant 2$ in Theorem~\ref{thm:irreducible} and Proposition~\ref{prop:irreducible} is harmless, since every hypersurface of degree $1$ in $\mathbb P^n$ is irreducible. Moreover, over an algebraically closed field, every hypersurface of degree $d \geqslant 2$ in $\mathbb P^1$ is reducible. Thus the assumption that
$n \geqslant 2$ in the statement of Proposition~\ref{prop:irreducible} is harmless as well.
